export const softEase = [0.23, 1, 0.32, 1] as const;

export type SlideDirection = "up" | "down" | "left" | "right";

const HOVER_QUERY = "(hover: hover) and (pointer: fine)";
const COARSE_QUERY = "(pointer: coarse)";

function useMediaQuery(query: string) {
  const [matches, setMatches] = React.useState(false);

  React.useEffect(() => {
    const mql = window.matchMedia(query);
    const update = () => setMatches(mql.matches);
    update();
    mql.addEventListener("change", update);
    return () => mql.removeEventListener("change", update);
  }, [query]);

  return matches;
}

export function useCanHover() {
  return useMediaQuery(HOVER_QUERY);
}

export function useCoarsePointer() {
  return useMediaQuery(COARSE_QUERY);
}

export function useMounted() {
  const [mounted, setMounted] = React.useState(false);
  React.useEffect(() => setMounted(true), []);
  return mounted;
}

export function useInViewEffect(
  ref: React.RefObject<Element | null>,
  enabled: boolean,
  once: boolean,
  margin: string,
) {
  const inView = useInView(ref, {
    once,
    amount: 0.35,
    margin: margin as `${number}px`,
  });
  return enabled ? inView : true;
}

export function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

export function mergeRefs<T>(
  ...refs: Array<React.Ref<T> | undefined>
): React.RefCallback<T> {
  return (node) => {
    for (const ref of refs) {
      if (!ref) continue;
      if (typeof ref === "function") ref(node);
      else (ref as React.MutableRefObject<T | null>).current = node;
    }
  };
}

"use client";

import * as React from "react";
import {
  motion,
  useMotionValue,
  useSpring,
  type HTMLMotionProps,
  type SpringOptions,
} from "motion/react";
import { cn } from "@/lib/utils";
import { useReduceMotion, useTempoTransition } from "../motion";

export type TiltProps = HTMLMotionProps<"div"> & {
  maxTilt?: number;
  perspective?: number;
  transition?: SpringOptions;
};

const defaultSpring: SpringOptions = {
  stiffness: 300,
  damping: 25,
  mass: 0.5,
};

export function Tilt({
  maxTilt = 10,
  perspective = 800,
  transition,
  className,
  style,
  onPointerMove,
  onPointerLeave,
  ...props
}: TiltProps) {
  const rawX = useMotionValue(0);
  const rawY = useMotionValue(0);
  const tempoSpring = useTempoTransition(transition ?? defaultSpring) as SpringOptions;
  const rotateX = useSpring(rawX, tempoSpring);
  const rotateY = useSpring(rawY, tempoSpring);
  const reduce = useReduceMotion();

  const handleMove = (event: React.PointerEvent<HTMLDivElement>) => {
    onPointerMove?.(event);
    if (reduce) return;
    const rect = event.currentTarget.getBoundingClientRect();
    const px = rect.width ? (event.clientX - rect.left) / rect.width : 0.5;
    const py = rect.height ? (event.clientY - rect.top) / rect.height : 0.5;
    rawY.set((px * 2 - 1) * maxTilt);
    rawX.set(-(py * 2 - 1) * maxTilt);
  };

  const handleLeave = (event: React.PointerEvent<HTMLDivElement>) => {
    onPointerLeave?.(event);
    rawX.set(0);
    rawY.set(0);
  };

  React.useEffect(() => {
    if (!reduce) return;
    rawX.jump(0);
    rawY.jump(0);
    rotateX.jump(0);
    rotateY.jump(0);
  }, [rawX, rawY, reduce, rotateX, rotateY]);

  return (
    <motion.div
      data-slot="tilt"
      className={cn("will-change-transform", className)}
      style={{
        rotateX,
        rotateY,
        transformPerspective: perspective,
        transformStyle: "preserve-3d",
        ...style,
      }}
      onPointerMove={handleMove}
      onPointerLeave={handleLeave}
      {...props}
    >
      {props.children}
    </motion.div>
  );
}

"use client";

import { useReducedMotion } from "motion/react";
import { useSyncExternalStore } from "react";

const subscribe = () => () => {};

export function useHydratedReducedMotion() {
  const reduce = useReducedMotion() ?? false;
  const mounted = useSyncExternalStore(
    subscribe,
    () => true,
    () => false,
  );
  return mounted ? reduce : false;
}
